// src/app/api/report/pdf/route.ts
import { NextResponse } from "next/server";
import { google } from "googleapis";
import { resolveDrivePathToViewerUrl } from "@/lib/google/drive";

function driveClient() {
  const auth = new google.auth.JWT({
    email: process.env.GOOGLE_CLIENT_EMAIL,
    key: (process.env.GOOGLE_PRIVATE_KEY || "").replace(/\\n/g, "\n"),
    scopes: ["https://www.googleapis.com/auth/drive.readonly"],
  });
  return google.drive({ version: "v3", auth });
}

const FOLDER_BY_KIND: Record<"safety" | "valve", string | undefined> = {
  safety: process.env.GOOGLE_DRIVE_SAFETY_ID,
  valve: process.env.GOOGLE_DRIVE_VALVE_ID,
};

export async function GET(req: Request) {
  try {
    const { searchParams } = new URL(req.url);
    const kind = (searchParams.get("kind") || "safety") as "safety" | "valve";
    const reportNo = (searchParams.get("reportNo") || "").trim();  // ตอนนี้จะเป็น token ตัวเลขแล้ว
    const hint = (searchParams.get("hint") || "").trim();
    const path = (searchParams.get("path") || "").trim();

    // ---------- แทนบล็อค path เดิมทั้งหมดด้วยอันนี้ ----------
const folderId = FOLDER_BY_KIND[kind]; // มีอยู่แล้วด้านบน
const drive = driveClient();

if (path) {
  const fileName = path.split("/").pop()?.trim() || "";
  if (fileName) {
    const esc = (s: string) => s.replace(/\\/g, "\\\\").replace(/'/g, "\\'");

    // 1) หาแบบ exact ในโฟลเดอร์ของ kind ก่อน (เร็ว + ตรงสุด)
    const q1 = [
      `'${folderId}' in parents`,
      `mimeType='application/pdf'`,
      `trashed=false`,
      `name='${esc(fileName)}'`,
    ].join(" and ");

    let { data } = await drive.files.list({
      q: q1,
      fields: "files(id,name,webViewLink,modifiedTime,size,parents)",
      orderBy: "modifiedTime desc",
      pageSize: 1,
      supportsAllDrives: true,
      includeItemsFromAllDrives: true,
    });

    let file = data.files?.[0];

    // 2) ถ้าไม่เจอในโฟลเดอร์ kind ให้หาแบบ exact ทั่วไดรฟ์ แล้วคัดตัวที่อยู่ในโฟลเดอร์ kind ถ้ามี
    if (!file) {
      const q2 = [
        `mimeType='application/pdf'`,
        `trashed=false`,
        `name='${esc(fileName)}'`,
      ].join(" and ");

      const { data: data2 } = await drive.files.list({
        q: q2,
        fields: "files(id,name,webViewLink,modifiedTime,size,parents)",
        orderBy: "modifiedTime desc",
        pageSize: 5,
        supportsAllDrives: true,
        includeItemsFromAllDrives: true,
      });

      file =
        data2.files?.find((f: any) => Array.isArray(f.parents) && f.parents.includes(folderId!)) ||
        data2.files?.[0];
    }

    if (file?.id) {
      const webViewLink = file.webViewLink || `https://drive.google.com/file/d/${file.id}/view?usp=drive_link`;
      return NextResponse.json({
        found: true,
        id: file.id,
        name: file.name,
        webViewLink,
        downloadUrl: `https://drive.google.com/uc?export=download&id=${file.id}`,
        iframeSrc: `https://drive.google.com/file/d/${file.id}/preview`,
        modifiedTime: file.modifiedTime,
        size: file.size,
        via: "path-exact",
      });
    }
    // ถ้ายังไม่เจอ ค่อยตกไป logic hint/reportNo ด้านล่างตามเดิม
  }
}
    // 2) สร้าง query ยืดหยุ่น: prior = hint (เช่น token ตัวเลข) รองลงมา = reportNo
    const needle = (hint || reportNo).replace(/'/g, "\\'");
    if (!needle) return NextResponse.json({ found: false, reason: "missing_query" });

    const q = [
      `'${folderId}' in parents`,
      `mimeType='application/pdf'`,
      `trashed=false`,
      `name contains '${needle}'`,
    ].join(" and ");

    const { data } = await drive.files.list({
      q,
      // เพิ่มฟิลด์ที่ UI ใช้
      fields: "files(id,name,webViewLink,modifiedTime,size)",
      orderBy: "modifiedTime desc",
      pageSize: 1,
      supportsAllDrives: true,
      includeItemsFromAllDrives: true,
    });

    const file = data.files?.[0];
    if (!file?.id) return NextResponse.json({ found: false });

    const webViewLink = file.webViewLink || `https://drive.google.com/file/d/${file.id}/view?usp=drive_link`;

    return NextResponse.json({
      found: true,
      id: file.id,
      name: file.name,
      webViewLink,
      downloadUrl: `https://drive.google.com/uc?export=download&id=${file.id}`,
      iframeSrc: `https://drive.google.com/file/d/${file.id}/preview`,
      modifiedTime: file.modifiedTime,
      size: file.size,
      via: "search",
    });
  } catch (e) {
    return NextResponse.json({ found: false, error: String(e) }, { status: 500 });
  }
}
